cols <- readRDS(file.path(Sys.getenv("S"),"cols.rds"))
ds <- c("county_elec_unharm","county_elec_harm_21_muni","county_elec_harm_21_cty","european_muni_unharm","european_muni_harm","federal_cty_unharm","federal_cty_harm","federal_muni_raw","federal_muni_unharm","federal_muni_harm_21","federal_muni_harm_25","federal_wkr_unharm","municipal_unharm","municipal_harm","municipal_harm_25","state_unharm","state_harm","state_harm_21","state_harm_23","state_harm_25","ltw_wkr_unharm","ltw_wkr_unharm_long","landrat_unharm","mayoral_unharm","mayoral_harm","county_council_seats")
for (d in ds) { x <- cols$col[cols$ds==d]; cat(sprintf("%-26s ags_name:%-5s ags_name_21/23/25:%-5s state_name:%-5s county_name:%-5s election_date:%-5s wkr_nr:%-5s\n", d, "ags_name"%in%x, any(grepl("^ags_name_",x)), "state_name"%in%x, "county_name"%in%x, "election_date"%in%x, "wkr_nr"%in%x)) }
